static long cal(int index, int last, int re, String S, long[] C, long[][][] dp) {
    final long MAX = Long.MAX_VALUE; // Assuming MAX is defined as Long.MAX_VALUE
    if (index == S.length()) {
        if (re == 1) {
            return 0;
        }
        return MAX;
    }
    if (dp[last][re][index] != -1) {
        return dp[last][re][index];
    }
    int cur = S.charAt(index) - '0';
    long res = cal(index + 1, 1 - last, re, S, C, dp);
    if (res != MAX) {
        res += (cur == last ? C[index] : 0);
    }
    if (re == 0) {
        long tmp = cal(index + 1, last, 1, S, C, dp);
        if (tmp != MAX) {
            tmp += (cur != last ? C[index] : 0);
        }
        res = Long.min(res, tmp);
    }
    return dp[last][re][index] = res;
}
